/* ===== DESIGN TOKENS ===== */
:root {
  --color-primary: #003F2D;
  --color-primary-light: #00573D;
  --color-primary-dark: #002B1E;
  --color-secondary: #012A2D;
  --color-accent: #C8A84E;
  --color-accent-light: #D4B96A;
  --color-accent-dark: #A88D35;
  --color-bg: #F8FAFC;
  --color-bg-alt: #F1F5F9;
  --color-bg-dark: #0A1628;
  --color-text: #1E293B;
  --color-text-secondary: #64748B;
  --color-text-light: #94A3B8;
  --color-white: #FFFFFF;
  --color-border: #E2E8F0;
  --color-border-light: rgba(255,255,255,0.15);
  --color-success: #16A34A;
  --color-error: #DC2626;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.04);
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --font-heading: 'Cinzel', Georgia, 'Times New Roman', serif;
  --font-body: 'Josefin Sans', 'Segoe UI', system-ui, sans-serif;
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
  --max-width: 1280px;
  --header-height: 72px;
}

/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font: inherit; cursor: pointer; border: none; background: none; color: inherit; }
input { font: inherit; }

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-primary-dark);
}

h1 { font-size: clamp(2.25rem, 4vw, 3.5rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.75rem, 3vw, 2.5rem); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.75rem); }
h4 { font-size: 1.125rem; }
h5 { font-size: 1rem; }

.section-label {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-accent-dark);
  margin-bottom: 0.75rem;
}

.section-title {
  font-family: var(--font-heading);
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-secondary);
  line-height: 1.7;
  max-width: 720px;
}

/* ===== LAYOUT ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 5rem 0;
}

.section-alt {
  background: var(--color-bg-alt);
}

.section-dark {
  background: var(--color-bg-dark);
  color: var(--color-white);
}

.section-dark .section-title,
.section-dark h2,
.section-dark h3 {
  color: var(--color-white);
}

.section-dark .section-subtitle {
  color: var(--color-text-light);
}

.section-dark .section-label {
  color: var(--color-accent-light);
}

/* ===== HEADER & NAVIGATION ===== */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
  height: var(--header-height);
  transition: background var(--transition-base);
}

.site-header.scrolled {
  background: rgba(255,255,255,0.98);
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: 0.02em;
  flex-shrink: 0;
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--color-primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: 1.25rem;
  font-weight: 800;
}

/* Main Nav */
.main-nav {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  height: 100%;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.5rem 0.875rem;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background var(--transition-fast);
  height: 100%;
  white-space: nowrap;
  cursor: pointer;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-primary);
  background: rgba(0,63,45,0.06);
}

.nav-link svg {
  width: 14px;
  height: 14px;
  transition: transform var(--transition-base);
}

/* Mega Menu */
.mega-menu-trigger { position: relative; }

.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: 2rem;
  min-width: 680px;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-base), transform var(--transition-base), visibility var(--transition-base);
  z-index: 999;
}

.mega-menu-trigger:hover .mega-menu,
.mega-menu-trigger:focus-within .mega-menu,
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.mega-menu-col h4 {
  font-family: var(--font-heading);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent-dark);
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--color-border);
}

.mega-menu-list {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.mega-menu-list a {
  display: block;
  padding: 0.5rem 0.75rem;
  font-size: 0.9rem;
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.mega-menu-list a:hover {
  color: var(--color-primary);
  background: rgba(0,63,45,0.05);
  padding-left: 1rem;
}

/* Mobile Nav Toggle */
.mobile-menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 0.5rem;
  cursor: pointer;
  z-index: 1001;
}

.mobile-menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-primary);
  border-radius: 2px;
  transition: transform var(--transition-base), opacity var(--transition-base);
}

.mobile-menu-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.mobile-menu-toggle.active span:nth-child(2) {
  opacity: 0;
}

.mobile-menu-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  z-index: 999;
  overflow-y: auto;
  padding: 1.5rem;
  transform: translateX(100%);
  transition: transform var(--transition-base);
}

.mobile-nav.active {
  transform: translateX(0);
}

.mobile-nav-link {
  display: block;
  padding: 1rem 0.5rem;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border);
  cursor: pointer;
}

.mobile-nav-accordion-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1rem 0.5rem;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border);
  cursor: pointer;
}

.mobile-nav-accordion-trigger svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-base);
}

.mobile-nav-accordion-trigger.active svg {
  transform: rotate(180deg);
}

.mobile-nav-sub {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  margin: 0.25rem 0;
}

.mobile-nav-sub.active {
  max-height: 500px;
}

.mobile-nav-sub a {
  display: block;
  padding: 0.75rem 1.5rem;
  font-size: 0.95rem;
  color: var(--color-text-secondary);
  border-bottom: 1px solid rgba(0,0,0,0.04);
}

.mobile-nav-sub a:hover {
  color: var(--color-primary);
}

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: var(--color-bg-dark);
  overflow: hidden;
  margin-top: var(--header-height);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0A1628 0%, #003F2D 40%, #012A2D 100%);
  z-index: 0;
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 20% 50%, rgba(200,168,78,0.15) 0%, transparent 60%),
    radial-gradient(ellipse at 80% 30%, rgba(0,63,45,0.3) 0%, transparent 50%);
}

.hero-pattern {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 60px 60px;
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
}

.hero-label {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--color-accent-light);
  margin-bottom: 1.5rem;
}

.hero-title {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  color: var(--color-white);
  line-height: 1.15;
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
}

.hero-subtitle {
  font-size: clamp(1.05rem, 1.5vw, 1.25rem);
  color: rgba(255,255,255,0.8);
  line-height: 1.7;
  margin-bottom: 2.5rem;
  max-width: 600px;
}

.hero-title-sm {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-radius: var(--radius-sm);
  transition: all var(--transition-base);
  white-space: nowrap;
  cursor: pointer;
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-primary-dark);
}

.btn-primary:hover {
  background: var(--color-accent-light);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(200,168,78,0.35);
}

.btn-outline {
  border: 2px solid rgba(255,255,255,0.3);
  color: var(--color-white);
}

.btn-outline:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
  background: rgba(200,168,78,0.08);
  transform: translateY(-1px);
}

.btn-outline-dark {
  border: 2px solid var(--color-primary);
  color: var(--color-primary);
}

.btn-outline-dark:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-text {
  padding: 0.5rem 0;
  color: var(--color-primary);
  background: none;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  letter-spacing: 0.04em;
  font-size: 0.8rem;
}

.btn-text:hover {
  border-bottom-color: var(--color-primary);
}

.btn-sm {
  padding: 0.625rem 1.25rem;
  font-size: 0.75rem;
}

.btn-lg {
  padding: 1rem 2.5rem;
  font-size: 0.9rem;
}

/* ===== CARDS ===== */
.card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.card-glass {
  background: rgba(255,255,255,0.8);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
}

.card-body {
  padding: 1.75rem;
}

.card-image {
  width: 100%;
  height: 220px;
  object-fit: cover;
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-primary));
}

.card-tag {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent-dark);
  margin-bottom: 0.75rem;
}

.card-title {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: 0.5rem;
  line-height: 1.4;
}

.card-text {
  font-size: 0.95rem;
  color: var(--color-text-secondary);
  line-height: 1.65;
  margin-bottom: 1.25rem;
}

.card-date {
  font-size: 0.8rem;
  color: var(--color-text-light);
  margin-top: 0.75rem;
}

/* ===== GRID SYSTEMS ===== */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 2rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2rem; }

/* ===== WHAT WE DO TABS ===== */
.tabs-section {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 3rem;
  align-items: start;
}

.tabs-nav {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  border-left: 2px solid var(--color-border);
}

.tab-btn {
  text-align: left;
  padding: 1.25rem 1.5rem;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-secondary);
  border-left: 2px solid transparent;
  margin-left: -2px;
  transition: all var(--transition-base);
  cursor: pointer;
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
}

.tab-btn:hover {
  color: var(--color-primary);
  background: rgba(0,63,45,0.03);
}

.tab-btn.active {
  color: var(--color-primary);
  border-left-color: var(--color-primary);
  background: rgba(0,63,45,0.05);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active {
  display: block;
}

.tab-panel-title {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: 1rem;
}

.tab-panel-text {
  font-size: 1.1rem;
  color: var(--color-text-secondary);
  line-height: 1.75;
  margin-bottom: 2rem;
}

/* ===== CAPABILITIES GRID ===== */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.capability-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition-base);
}

.capability-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-primary);
}

.capability-icon {
  width: 48px;
  height: 48px;
  background: rgba(0,63,45,0.08);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--color-primary);
  font-size: 1.25rem;
}

.capability-title {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: 0.75rem;
}

.capability-text {
  font-size: 0.9rem;
  color: var(--color-text-secondary);
  line-height: 1.65;
}

/* ===== FEATURED INSIGHTS ===== */
.featured-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.insight-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  border: 1px solid var(--color-border);
}

.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.insight-card-image {
  height: 180px;
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-secondary));
  position: relative;
  overflow: hidden;
}

.insight-card-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.4), transparent);
}

.insight-card-body {
  padding: 1.5rem;
}

/* ===== ANNOUNCEMENT BANNER ===== */
.announcement-banner {
  background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
  padding: 2rem 0;
  position: relative;
  overflow: hidden;
}

.announcement-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 50%, rgba(200,168,78,0.15) 0%, transparent 60%);
}

.announcement-inner {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}

.announcement-text {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-white);
}

.announcement-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  background: var(--color-accent);
  border-radius: 50%;
  margin-right: 0.75rem;
  animation: pulse 2s infinite;
}

/* ===== NEWSLETTER ===== */
.newsletter-section {
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-secondary));
  padding: 4rem 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.newsletter-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, rgba(200,168,78,0.1) 0%, transparent 60%);
}

.newsletter-content {
  position: relative;
  z-index: 1;
  max-width: 600px;
  margin: 0 auto;
}

.newsletter-form {
  display: flex;
  gap: 0.75rem;
  max-width: 480px;
  margin: 2rem auto 0;
}

.newsletter-input {
  flex: 1;
  padding: 0.875rem 1.25rem;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,0.1);
  color: var(--color-white);
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition-fast);
}

.newsletter-input::placeholder {
  color: rgba(255,255,255,0.5);
}

.newsletter-input:focus {
  border-color: var(--color-accent);
}

/* ===== COMMITMENT PILLARS ===== */
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.commitment-card {
  text-align: center;
  padding: 2rem 1.5rem;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.commitment-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-primary);
}

.commitment-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 1.25rem;
  background: rgba(0,63,45,0.08);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--color-primary);
}

/* ===== SERVICE CATEGORIES ===== */
.service-categories-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.service-category-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.service-category-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-primary);
}

.service-category-card.featured {
  border-color: var(--color-accent);
  background: linear-gradient(135deg, rgba(200,168,78,0.05), var(--color-white));
}

.service-category-icon {
  width: 52px;
  height: 52px;
  background: rgba(0,63,45,0.08);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  color: var(--color-primary);
  font-size: 1.35rem;
}

.service-category-title {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: 0.75rem;
}

.service-category-text {
  font-size: 0.95rem;
  color: var(--color-text-secondary);
  line-height: 1.7;
  margin-bottom: 1.5rem;
  flex: 1;
}

/* ===== CAROUSEL ===== */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-base);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 0.25rem;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--color-border);
  background: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast);
  color: var(--color-primary);
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-white);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-border);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--color-primary);
  width: 24px;
  border-radius: 4px;
}

/* ===== TESTIMONIAL ===== */
.testimonial {
  background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
  padding: 4rem;
  border-radius: var(--radius-xl);
  color: var(--color-white);
  position: relative;
  overflow: hidden;
}

.testimonial::before {
  content: '"';
  position: absolute;
  top: 0;
  left: 2rem;
  font-family: var(--font-heading);
  font-size: 12rem;
  opacity: 0.08;
  line-height: 1;
}

.testimonial-text {
  font-size: 1.25rem;
  line-height: 1.8;
  font-style: italic;
  margin-bottom: 2rem;
  position: relative;
  z-index: 1;
}

.testimonial-author {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
}

.testimonial-role {
  font-size: 0.85rem;
  opacity: 0.7;
  margin-top: 0.25rem;
}

/* ===== FEATURED TOPICS ===== */
.featured-topics-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.featured-topic-link {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  font-size: 0.95rem;
  color: var(--color-text);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  border: 1px solid var(--color-border);
}

.featured-topic-link:hover {
  background: rgba(0,63,45,0.05);
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.featured-topic-link svg {
  width: 16px;
  height: 16px;
  color: var(--color-accent);
  flex-shrink: 0;
}

/* ===== RELATED SERVICES ===== */
.related-services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.related-service-card {
  padding: 1.5rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.related-service-card:hover {
  border-color: var(--color-primary);
  background: rgba(0,63,45,0.03);
}

/* ===== SIDEBAR LAYOUT ===== */
.content-with-sidebar {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 3rem;
  align-items: start;
}

.sidebar-title {
  font-family: var(--font-heading);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent-dark);
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--color-border);
}

/* ===== DEAL FLOW CTA ===== */
.deal-flow-cta {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: 3rem;
  text-align: center;
}

.deal-flow-cta h3 {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: var(--color-primary-dark);
}

.deal-flow-cta p {
  color: var(--color-text-secondary);
  margin-bottom: 2rem;
  font-size: 1.05rem;
}

/* ===== PARTNERSHIP HIGHLIGHT ===== */
.partnership-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: var(--color-white);
}

.partnership-content {
  padding: 3rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.partnership-image {
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-secondary));
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 320px;
}

.partnership-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}

.partnership-stat-value {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 700;
  color: var(--color-primary);
  line-height: 1;
}

.partnership-stat-label {
  font-size: 0.8rem;
  color: var(--color-text-secondary);
  margin-top: 0.25rem;
}

/* ===== PAGE HERO (SECONDARY) ===== */
.page-hero {
  position: relative;
  padding: 7rem 0 5rem;
  margin-top: var(--header-height);
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-primary-dark));
  overflow: hidden;
}

.page-hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(200,168,78,0.1) 0%, transparent 60%);
}

.page-hero-content {
  position: relative;
  z-index: 1;
  max-width: 720px;
}

.page-hero-content h1 {
  color: var(--color-white);
}

.page-hero-content p {
  color: rgba(255,255,255,0.8);
  font-size: 1.15rem;
  line-height: 1.7;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
  font-size: 0.8rem;
  color: rgba(255,255,255,0.6);
}

.breadcrumb a {
  color: var(--color-accent-light);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--color-accent);
}

.breadcrumb svg {
  width: 14px;
  height: 14px;
}

/* ===== INTRO STATEMENT ===== */
.intro-statement {
  font-size: 1.2rem;
  color: var(--color-text-secondary);
  line-height: 1.8;
  max-width: 800px;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--color-bg-dark);
  color: var(--color-white);
  padding: 5rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand-text {
  color: rgba(255,255,255,0.6);
  font-size: 0.9rem;
  line-height: 1.7;
  margin-top: 1rem;
  max-width: 280px;
}

.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent-light);
  margin-bottom: 1.25rem;
}

.footer-col a {
  display: block;
  padding: 0.35rem 0;
  font-size: 0.9rem;
  color: rgba(255,255,255,0.65);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 1rem;
  font-size: 0.8rem;
  color: rgba(255,255,255,0.4);
}

.footer-bottom-links {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.footer-bottom-links a {
  color: rgba(255,255,255,0.5);
  transition: color var(--transition-fast);
}

.footer-bottom-links a:hover {
  color: var(--color-accent);
}

/* ===== PAGE-SPECIFIC: Invest Detail ===== */
.capabilities-with-sidebar {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 3rem;
  align-items: start;
}

.sidebar-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  position: sticky;
  top: calc(var(--header-height) + 2rem);
}

/* ===== INTRO + IMAGE SECTION ===== */
.intro-with-image {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.intro-image {
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-primary));
  border-radius: var(--radius-xl);
  min-height: 340px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-family: var(--font-heading);
  font-size: 1.5rem;
  opacity: 0.9;
}

/* ===== ANIMATIONS ===== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.fade-in-up {
  animation: fadeInUp 0.6s ease forwards;
}

/* ===== UTILITIES ===== */
.text-center { text-align: center; }
.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }
.mb-5 { margin-bottom: 3rem; }
.mt-1 { margin-top: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }
.mt-5 { margin-top: 3rem; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

/* Page-specific: invest detail sidebar-contact CTA */
.sidebar-cta {
  display: block;
  text-align: center;
  padding: 0.875rem;
  background: var(--color-accent);
  color: var(--color-primary-dark);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-radius: var(--radius-sm);
  margin-top: 1.5rem;
  transition: all var(--transition-fast);
}

.sidebar-cta:hover {
  background: var(--color-accent-light);
}

/* Featured partners cards */
.partner-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
}

.partner-logo-placeholder {
  width: 80px;
  height: 80px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 0.7rem;
  color: var(--color-text-light);
  text-transform: uppercase;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1200px) {
  .container { padding: 0 1.25rem; }
}

@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .service-categories-grid { grid-template-columns: repeat(2, 1fr); }
  .related-services-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .content-with-sidebar { grid-template-columns: 1fr; }
  .capabilities-with-sidebar { grid-template-columns: 1fr; }
  .tabs-section { grid-template-columns: 1fr; }
  .mega-menu { min-width: 500px; }
  .intro-with-image { grid-template-columns: 1fr; }
  .partnership-card { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  :root { --header-height: 64px; }

  .main-nav { display: none; }
  .mobile-menu-toggle { display: flex; }
  .mobile-nav { display: block; }

  .hero { min-height: 70vh; padding: 3rem 0; }
  .hero-title { font-size: clamp(1.75rem, 5vw, 2.5rem); }

  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: 1fr; }
  .commitment-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .service-categories-grid { grid-template-columns: 1fr; }
  .related-services-grid { grid-template-columns: 1fr; }
  .featured-insights-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }

  .section { padding: 3rem 0; }

  .tabs-nav {
    flex-direction: row;
    overflow-x: auto;
    border-left: none;
    border-bottom: 2px solid var(--color-border);
    gap: 0;
    padding-bottom: 0;
  }

  .tab-btn {
    border-left: none;
    border-bottom: 2px solid transparent;
    margin-left: 0;
    margin-bottom: -2px;
    white-space: nowrap;
    border-radius: var(--radius-sm) var(--radius-sm) 0 0;
    padding: 0.75rem 1rem;
    font-size: 0.85rem;
  }

  .tab-btn.active {
    border-left-color: transparent;
    border-bottom-color: var(--color-primary);
  }

  .newsletter-form { flex-direction: column; }
  .announcement-inner { flex-direction: column; text-align: center; }
  .testimonial { padding: 2rem; }
  .partnership-stats { grid-template-columns: 1fr; }
  .page-hero { padding: 5rem 0 3rem; }
}

@media (max-width: 480px) {
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.4rem; }
  .container { padding: 0 1rem; }
  .btn-lg { padding: 0.75rem 1.5rem; font-size: 0.8rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ===== DESIGN TOKENS ===== */
:root {
  --color-primary: #003F2D;
  --color-primary-light: #00573D;
  --color-primary-dark: #002B1E;
  --color-secondary: #012A2D;
  --color-accent: #C8A84E;
  --color-accent-light: #D4B96A;
  --color-accent-dark: #A88D35;
  --color-bg: #F8FAFC;
  --color-bg-alt: #F1F5F9;
  --color-bg-dark: #0A1628;
  --color-text: #1E293B;
  --color-text-secondary: #64748B;
  --color-text-light: #94A3B8;
  --color-white: #FFFFFF;
  --color-border: #E2E8F0;
  --color-border-light: rgba(255,255,255,0.15);
  --color-success: #16A34A;
  --color-error: #DC2626;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.04);
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --font-heading: 'Cinzel', Georgia, 'Times New Roman', serif;
  --font-body: 'Josefin Sans', 'Segoe UI', system-ui, sans-serif;
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
  --max-width: 1280px;
  --header-height: 72px;
}

/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font: inherit; cursor: pointer; border: none; background: none; color: inherit; }
input { font: inherit; }

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-primary-dark);
}

h1 { font-size: clamp(2.25rem, 4vw, 3.5rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.75rem, 3vw, 2.5rem); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.75rem); }
h4 { font-size: 1.125rem; }
h5 { font-size: 1rem; }

.section-label {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-accent-dark);
  margin-bottom: 0.75rem;
}

.section-title {
  font-family: var(--font-heading);
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-secondary);
  line-height: 1.7;
  max-width: 720px;
}

/* ===== LAYOUT ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 5rem 0;
}

.section-alt {
  background: var(--color-bg-alt);
}

.section-dark {
  background: var(--color-bg-dark);
  color: var(--color-white);
}

.section-dark .section-title,
.section-dark h2,
.section-dark h3 {
  color: var(--color-white);
}

.section-dark .section-subtitle {
  color: var(--color-text-light);
}

.section-dark .section-label {
  color: var(--color-accent-light);
}

/* ===== HEADER & NAVIGATION ===== */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
  height: var(--header-height);
  transition: background var(--transition-base);
}

.site-header.scrolled {
  background: rgba(255,255,255,0.98);
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: 0.02em;
  flex-shrink: 0;
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--color-primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: 1.25rem;
  font-weight: 800;
}

/* Main Nav */
.main-nav {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  height: 100%;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.5rem 0.875rem;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background var(--transition-fast);
  height: 100%;
  white-space: nowrap;
  cursor: pointer;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-primary);
  background: rgba(0,63,45,0.06);
}

.nav-link svg {
  width: 14px;
  height: 14px;
  transition: transform var(--transition-base);
}

/* Mega Menu */
.mega-menu-trigger { position: relative; }

.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: 2rem;
  min-width: 680px;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-base), transform var(--transition-base), visibility var(--transition-base);
  z-index: 999;
}

.mega-menu-trigger:hover .mega-menu,
.mega-menu-trigger:focus-within .mega-menu,
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.mega-menu-col h4 {
  font-family: var(--font-heading);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent-dark);
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--color-border);
}

.mega-menu-list {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.mega-menu-list a {
  display: block;
  padding: 0.5rem 0.75rem;
  font-size: 0.9rem;
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.mega-menu-list a:hover {
  color: var(--color-primary);
  background: rgba(0,63,45,0.05);
  padding-left: 1rem;
}

/* Mobile Nav Toggle */
.mobile-menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 0.5rem;
  cursor: pointer;
  z-index: 1001;
}

.mobile-menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-primary);
  border-radius: 2px;
  transition: transform var(--transition-base), opacity var(--transition-base);
}

.mobile-menu-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.mobile-menu-toggle.active span:nth-child(2) {
  opacity: 0;
}

.mobile-menu-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  z-index: 999;
  overflow-y: auto;
  padding: 1.5rem;
  transform: translateX(100%);
  transition: transform var(--transition-base);
}

.mobile-nav.active {
  transform: translateX(0);
}

.mobile-nav-link {
  display: block;
  padding: 1rem 0.5rem;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border);
  cursor: pointer;
}

.mobile-nav-accordion-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1rem 0.5rem;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border);
  cursor: pointer;
}

.mobile-nav-accordion-trigger svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-base);
}

.mobile-nav-accordion-trigger.active svg {
  transform: rotate(180deg);
}

.mobile-nav-sub {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  margin: 0.25rem 0;
}

.mobile-nav-sub.active {
  max-height: 500px;
}

.mobile-nav-sub a {
  display: block;
  padding: 0.75rem 1.5rem;
  font-size: 0.95rem;
  color: var(--color-text-secondary);
  border-bottom: 1px solid rgba(0,0,0,0.04);
}

.mobile-nav-sub a:hover {
  color: var(--color-primary);
}

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: var(--color-bg-dark);
  overflow: hidden;
  margin-top: var(--header-height);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0A1628 0%, #003F2D 40%, #012A2D 100%);
  z-index: 0;
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 20% 50%, rgba(200,168,78,0.15) 0%, transparent 60%),
    radial-gradient(ellipse at 80% 30%, rgba(0,63,45,0.3) 0%, transparent 50%);
}

.hero-pattern {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 60px 60px;
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
}

.hero-label {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--color-accent-light);
  margin-bottom: 1.5rem;
}

.hero-title {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  color: var(--color-white);
  line-height: 1.15;
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
}

.hero-subtitle {
  font-size: clamp(1.05rem, 1.5vw, 1.25rem);
  color: rgba(255,255,255,0.8);
  line-height: 1.7;
  margin-bottom: 2.5rem;
  max-width: 600px;
}

.hero-title-sm {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-radius: var(--radius-sm);
  transition: all var(--transition-base);
  white-space: nowrap;
  cursor: pointer;
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-primary-dark);
}

.btn-primary:hover {
  background: var(--color-accent-light);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(200,168,78,0.35);
}

.btn-outline {
  border: 2px solid rgba(255,255,255,0.3);
  color: var(--color-white);
}

.btn-outline:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
  background: rgba(200,168,78,0.08);
  transform: translateY(-1px);
}

.btn-outline-dark {
  border: 2px solid var(--color-primary);
  color: var(--color-primary);
}

.btn-outline-dark:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-text {
  padding: 0.5rem 0;
  color: var(--color-primary);
  background: none;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  letter-spacing: 0.04em;
  font-size: 0.8rem;
}

.btn-text:hover {
  border-bottom-color: var(--color-primary);
}

.btn-sm {
  padding: 0.625rem 1.25rem;
  font-size: 0.75rem;
}

.btn-lg {
  padding: 1rem 2.5rem;
  font-size: 0.9rem;
}

/* ===== CARDS ===== */
.card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.card-glass {
  background: rgba(255,255,255,0.8);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
}

.card-body {
  padding: 1.75rem;
}

.card-image {
  width: 100%;
  height: 220px;
  object-fit: cover;
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-primary));
}

.card-tag {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent-dark);
  margin-bottom: 0.75rem;
}

.card-title {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: 0.5rem;
  line-height: 1.4;
}

.card-text {
  font-size: 0.95rem;
  color: var(--color-text-secondary);
  line-height: 1.65;
  margin-bottom: 1.25rem;
}

.card-date {
  font-size: 0.8rem;
  color: var(--color-text-light);
  margin-top: 0.75rem;
}

/* ===== GRID SYSTEMS ===== */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 2rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2rem; }

/* ===== WHAT WE DO TABS ===== */
.tabs-section {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 3rem;
  align-items: start;
}

.tabs-nav {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  border-left: 2px solid var(--color-border);
}

.tab-btn {
  text-align: left;
  padding: 1.25rem 1.5rem;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-secondary);
  border-left: 2px solid transparent;
  margin-left: -2px;
  transition: all var(--transition-base);
  cursor: pointer;
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
}

.tab-btn:hover {
  color: var(--color-primary);
  background: rgba(0,63,45,0.03);
}

.tab-btn.active {
  color: var(--color-primary);
  border-left-color: var(--color-primary);
  background: rgba(0,63,45,0.05);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active {
  display: block;
}

.tab-panel-title {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: 1rem;
}

.tab-panel-text {
  font-size: 1.1rem;
  color: var(--color-text-secondary);
  line-height: 1.75;
  margin-bottom: 2rem;
}

/* ===== CAPABILITIES GRID ===== */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.capability-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition-base);
}

.capability-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-primary);
}

.capability-icon {
  width: 48px;
  height: 48px;
  background: rgba(0,63,45,0.08);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--color-primary);
  font-size: 1.25rem;
}

.capability-title {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: 0.75rem;
}

.capability-text {
  font-size: 0.9rem;
  color: var(--color-text-secondary);
  line-height: 1.65;
}

/* ===== FEATURED INSIGHTS ===== */
.featured-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.insight-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  border: 1px solid var(--color-border);
}

.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.insight-card-image {
  height: 180px;
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-secondary));
  position: relative;
  overflow: hidden;
}

.insight-card-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.4), transparent);
}

.insight-card-body {
  padding: 1.5rem;
}

/* ===== ANNOUNCEMENT BANNER ===== */
.announcement-banner {
  background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
  padding: 2rem 0;
  position: relative;
  overflow: hidden;
}

.announcement-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 50%, rgba(200,168,78,0.15) 0%, transparent 60%);
}

.announcement-inner {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}

.announcement-text {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-white);
}

.announcement-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  background: var(--color-accent);
  border-radius: 50%;
  margin-right: 0.75rem;
  animation: pulse 2s infinite;
}

/* ===== NEWSLETTER ===== */
.newsletter-section {
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-secondary));
  padding: 4rem 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.newsletter-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, rgba(200,168,78,0.1) 0%, transparent 60%);
}

.newsletter-content {
  position: relative;
  z-index: 1;
  max-width: 600px;
  margin: 0 auto;
}

.newsletter-form {
  display: flex;
  gap: 0.75rem;
  max-width: 480px;
  margin: 2rem auto 0;
}

.newsletter-input {
  flex: 1;
  padding: 0.875rem 1.25rem;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,0.1);
  color: var(--color-white);
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition-fast);
}

.newsletter-input::placeholder {
  color: rgba(255,255,255,0.5);
}

.newsletter-input:focus {
  border-color: var(--color-accent);
}

/* ===== COMMITMENT PILLARS ===== */
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.commitment-card {
  text-align: center;
  padding: 2rem 1.5rem;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.commitment-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-primary);
}

.commitment-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 1.25rem;
  background: rgba(0,63,45,0.08);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--color-primary);
}

/* ===== SERVICE CATEGORIES ===== */
.service-categories-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.service-category-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.service-category-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-primary);
}

.service-category-card.featured {
  border-color: var(--color-accent);
  background: linear-gradient(135deg, rgba(200,168,78,0.05), var(--color-white));
}

.service-category-icon {
  width: 52px;
  height: 52px;
  background: rgba(0,63,45,0.08);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  color: var(--color-primary);
  font-size: 1.35rem;
}

.service-category-title {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: 0.75rem;
}

.service-category-text {
  font-size: 0.95rem;
  color: var(--color-text-secondary);
  line-height: 1.7;
  margin-bottom: 1.5rem;
  flex: 1;
}

/* ===== CAROUSEL ===== */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-base);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 0.25rem;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--color-border);
  background: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast);
  color: var(--color-primary);
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-white);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-border);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--color-primary);
  width: 24px;
  border-radius: 4px;
}

/* ===== TESTIMONIAL ===== */
.testimonial {
  background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
  padding: 4rem;
  border-radius: var(--radius-xl);
  color: var(--color-white);
  position: relative;
  overflow: hidden;
}

.testimonial::before {
  content: '"';
  position: absolute;
  top: 0;
  left: 2rem;
  font-family: var(--font-heading);
  font-size: 12rem;
  opacity: 0.08;
  line-height: 1;
}

.testimonial-text {
  font-size: 1.25rem;
  line-height: 1.8;
  font-style: italic;
  margin-bottom: 2rem;
  position: relative;
  z-index: 1;
}

.testimonial-author {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
}

.testimonial-role {
  font-size: 0.85rem;
  opacity: 0.7;
  margin-top: 0.25rem;
}

/* ===== FEATURED TOPICS ===== */
.featured-topics-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.featured-topic-link {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  font-size: 0.95rem;
  color: var(--color-text);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  border: 1px solid var(--color-border);
}

.featured-topic-link:hover {
  background: rgba(0,63,45,0.05);
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.featured-topic-link svg {
  width: 16px;
  height: 16px;
  color: var(--color-accent);
  flex-shrink: 0;
}

/* ===== RELATED SERVICES ===== */
.related-services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.related-service-card {
  padding: 1.5rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.related-service-card:hover {
  border-color: var(--color-primary);
  background: rgba(0,63,45,0.03);
}

/* ===== SIDEBAR LAYOUT ===== */
.content-with-sidebar {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 3rem;
  align-items: start;
}

.sidebar-title {
  font-family: var(--font-heading);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent-dark);
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--color-border);
}

/* ===== DEAL FLOW CTA ===== */
.deal-flow-cta {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: 3rem;
  text-align: center;
}

.deal-flow-cta h3 {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: var(--color-primary-dark);
}

.deal-flow-cta p {
  color: var(--color-text-secondary);
  margin-bottom: 2rem;
  font-size: 1.05rem;
}

/* ===== PARTNERSHIP HIGHLIGHT ===== */
.partnership-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: var(--color-white);
}

.partnership-content {
  padding: 3rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.partnership-image {
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-secondary));
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 320px;
}

.partnership-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}

.partnership-stat-value {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 700;
  color: var(--color-primary);
  line-height: 1;
}

.partnership-stat-label {
  font-size: 0.8rem;
  color: var(--color-text-secondary);
  margin-top: 0.25rem;
}

/* ===== PAGE HERO (SECONDARY) ===== */
.page-hero {
  position: relative;
  padding: 7rem 0 5rem;
  margin-top: var(--header-height);
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-primary-dark));
  overflow: hidden;
}

.page-hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(200,168,78,0.1) 0%, transparent 60%);
}

.page-hero-content {
  position: relative;
  z-index: 1;
  max-width: 720px;
}

.page-hero-content h1 {
  color: var(--color-white);
}

.page-hero-content p {
  color: rgba(255,255,255,0.8);
  font-size: 1.15rem;
  line-height: 1.7;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
  font-size: 0.8rem;
  color: rgba(255,255,255,0.6);
}

.breadcrumb a {
  color: var(--color-accent-light);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--color-accent);
}

.breadcrumb svg {
  width: 14px;
  height: 14px;
}

/* ===== INTRO STATEMENT ===== */
.intro-statement {
  font-size: 1.2rem;
  color: var(--color-text-secondary);
  line-height: 1.8;
  max-width: 800px;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--color-bg-dark);
  color: var(--color-white);
  padding: 5rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand-text {
  color: rgba(255,255,255,0.6);
  font-size: 0.9rem;
  line-height: 1.7;
  margin-top: 1rem;
  max-width: 280px;
}

.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent-light);
  margin-bottom: 1.25rem;
}

.footer-col a {
  display: block;
  padding: 0.35rem 0;
  font-size: 0.9rem;
  color: rgba(255,255,255,0.65);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 1rem;
  font-size: 0.8rem;
  color: rgba(255,255,255,0.4);
}

.footer-bottom-links {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.footer-bottom-links a {
  color: rgba(255,255,255,0.5);
  transition: color var(--transition-fast);
}

.footer-bottom-links a:hover {
  color: var(--color-accent);
}

/* ===== PAGE-SPECIFIC: Invest Detail ===== */
.capabilities-with-sidebar {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 3rem;
  align-items: start;
}

.sidebar-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  position: sticky;
  top: calc(var(--header-height) + 2rem);
}

/* ===== INTRO + IMAGE SECTION ===== */
.intro-with-image {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.intro-image {
  background: linear-gradient(135deg, var(--color-bg-dark), var(--color-primary));
  border-radius: var(--radius-xl);
  min-height: 340px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-family: var(--font-heading);
  font-size: 1.5rem;
  opacity: 0.9;
}

/* ===== ANIMATIONS ===== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.fade-in-up {
  animation: fadeInUp 0.6s ease forwards;
}

/* ===== UTILITIES ===== */
.text-center { text-align: center; }
.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }
.mb-5 { margin-bottom: 3rem; }
.mt-1 { margin-top: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }
.mt-5 { margin-top: 3rem; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

/* Page-specific: invest detail sidebar-contact CTA */
.sidebar-cta {
  display: block;
  text-align: center;
  padding: 0.875rem;
  background: var(--color-accent);
  color: var(--color-primary-dark);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-radius: var(--radius-sm);
  margin-top: 1.5rem;
  transition: all var(--transition-fast);
}

.sidebar-cta:hover {
  background: var(--color-accent-light);
}

/* Featured partners cards */
.partner-card {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
}

.partner-logo-placeholder {
  width: 80px;
  height: 80px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 0.7rem;
  color: var(--color-text-light);
  text-transform: uppercase;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1200px) {
  .container { padding: 0 1.25rem; }
}

@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .service-categories-grid { grid-template-columns: repeat(2, 1fr); }
  .related-services-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .content-with-sidebar { grid-template-columns: 1fr; }
  .capabilities-with-sidebar { grid-template-columns: 1fr; }
  .tabs-section { grid-template-columns: 1fr; }
  .mega-menu { min-width: 500px; }
  .intro-with-image { grid-template-columns: 1fr; }
  .partnership-card { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  :root { --header-height: 64px; }

  .main-nav { display: none; }
  .mobile-menu-toggle { display: flex; }
  .mobile-nav { display: block; }

  .hero { min-height: 70vh; padding: 3rem 0; }
  .hero-title { font-size: clamp(1.75rem, 5vw, 2.5rem); }

  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: 1fr; }
  .commitment-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .service-categories-grid { grid-template-columns: 1fr; }
  .related-services-grid { grid-template-columns: 1fr; }
  .featured-insights-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }

  .section { padding: 3rem 0; }

  .tabs-nav {
    flex-direction: row;
    overflow-x: auto;
    border-left: none;
    border-bottom: 2px solid var(--color-border);
    gap: 0;
    padding-bottom: 0;
  }

  .tab-btn {
    border-left: none;
    border-bottom: 2px solid transparent;
    margin-left: 0;
    margin-bottom: -2px;
    white-space: nowrap;
    border-radius: var(--radius-sm) var(--radius-sm) 0 0;
    padding: 0.75rem 1rem;
    font-size: 0.85rem;
  }

  .tab-btn.active {
    border-left-color: transparent;
    border-bottom-color: var(--color-primary);
  }

  .newsletter-form { flex-direction: column; }
  .announcement-inner { flex-direction: column; text-align: center; }
  .testimonial { padding: 2rem; }
  .partnership-stats { grid-template-columns: 1fr; }
  .page-hero { padding: 5rem 0 3rem; }
}

@media (max-width: 480px) {
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.4rem; }
  .container { padding: 0 1rem; }
  .btn-lg { padding: 0.75rem 1.5rem; font-size: 0.8rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

